  (6096, 2154, 73, timestamptz '2026-10-22 09:04:18.509+00', timestamptz '2026-10-22 10:16:59.541+00', 'samsara_stay', 1, date '2026-10-21', timestamptz '2026-10-22 08:51:46+00', NULL::timestamptz, 14, timestamptz '2026-10-22T10:19:41.500Z', timestamptz '2026-10-22T10:33:52.533Z', 'review', 'change', 'one_judge:own_stop', 'stop', 'no_free_stay', 'stop'),
  (8752, 1803, NULL::int, NULL::timestamptz, NULL::timestamptz, NULL, 3, date '2026-10-09', timestamptz '2026-10-09 19:43:22+00', NULL::timestamptz, NULL::int, NULL::timestamptz, NULL::timestamptz, NULL, 'blank', 'no_samsara_presence', 'blank', 'far_park', 'blank'),
  (9046, 2131, NULL::int, NULL::timestamptz, NULL::timestamptz, NULL, 2, date '2026-11-01', timestamptz '2026-11-02 16:43:01+00', NULL::timestamptz, NULL::int, NULL::timestamptz, NULL::timestamptz, NULL, 'blank', 'no_samsara_presence', 'blank', 'other_day', 'blank')
) AS x (visit_id, old_lid, cur_min, cur_arr, cur_dep, cur_src, cur_veh, cur_date, cur_comp, cur_bonus, new_min, new_arr, new_dep, new_src, action, method, kind, held_as, split_ref);
DO $g$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.visit_time_on_site_corrections WHERE run_id = 'tos-person-20261117' AND superseded_at IS NULL AND status = 'applied';
  IF n <> 46 THEN RAISE EXCEPTION 'rollback person page: % current applied rows of the run, expected 46 (applied?)', n; END IF;
  PERFORM 1 FROM public.visits v WHERE v.id IN (SELECT visit_id FROM _r) FOR UPDATE;
  IF EXISTS (SELECT 1 FROM _r r JOIN public.visits v ON v.id = r.visit_id
              WHERE (v.duration_minutes, v.actual_arrival_at, v.actual_departure_at, v.time_on_site_source) IS DISTINCT FROM (r.new_min, r.new_arr, r.new_dep, r.new_src)) THEN
    RAISE EXCEPTION 'rollback person page: a visit no longer holds the migration''s value'; END IF;
END $g$;
DO $w$
DECLARE v_hdr text := current_setting('request.headers', true); n int;
BEGIN
  PERFORM set_config('request.headers', (coalesce(nullif(v_hdr, '')::jsonb, '{}'::jsonb)
    || jsonb_build_object('x-app-source', 'time-on-site-recheck-2026', 'x-change-reason', 'Rollback of 2026-11-17_2150_time_on_site_person_page.sql'))::text, true);
  UPDATE public.visit_time_on_site_corrections SET status = 'rolled_back', rolled_back_at = now(), superseded_at = now()
   WHERE run_id = 'tos-person-20261117' AND superseded_at IS NULL;
  GET DIAGNOSTICS n = row_count; IF n <> 46 THEN RAISE EXCEPTION 'rollback: % run rows, expected 46', n; END IF;
  UPDATE public.visit_time_on_site_corrections l SET superseded_at = NULL FROM _r r WHERE l.id = r.old_lid;
  GET DIAGNOSTICS n = row_count; IF n <> 46 THEN RAISE EXCEPTION 'rollback: % previous rows restored, expected 46', n; END IF;
  UPDATE public.visits v SET duration_minutes = r.cur_min, actual_arrival_at = r.cur_arr, actual_departure_at = r.cur_dep, time_on_site_source = r.cur_src
    FROM _r r WHERE v.id = r.visit_id AND r.action = 'change';
  GET DIAGNOSTICS n = row_count; IF n <> 13 THEN RAISE EXCEPTION 'rollback: % visits restored, expected 13', n; END IF;
  PERFORM set_config('request.headers', coalesce(v_hdr, ''), true);
END $w$;
DO $v$ BEGIN
  IF EXISTS (SELECT 1 FROM _r r JOIN public.visits v ON v.id = r.visit_id
              WHERE (v.duration_minutes, v.actual_arrival_at, v.actual_departure_at, v.time_on_site_source) IS DISTINCT FROM (r.cur_min, r.cur_arr, r.cur_dep, r.cur_src)) THEN
    RAISE EXCEPTION 'VERIFY rollback: a visit is not back to its old value'; END IF;
  IF EXISTS (SELECT 1 FROM _r r WHERE NOT EXISTS (SELECT 1 FROM public.visit_time_on_site_corrections l WHERE l.id = r.old_lid AND l.superseded_at IS NULL)) THEN
    RAISE EXCEPTION 'VERIFY rollback: a previous row is not current'; END IF;
  IF EXISTS (SELECT 1 FROM public.visit_time_on_site_corrections WHERE run_id = 'tos-person-20261117' AND superseded_at IS NULL) THEN
    RAISE EXCEPTION 'VERIFY rollback: a run row is still current'; END IF;
  IF (public.fn_time_on_site_checks()->>'T7')::int <> 0 THEN RAISE EXCEPTION 'VERIFY rollback: T7 is not 0'; END IF;
END $v$;
COMMIT;
